import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.ChIlRNAd.js";const m=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/overview.md","filePath":"en/guide/overview.md"}'),o={name:"en/guide/overview.md"};function n(i,e,l,d,h,u){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>The <strong>Overview</strong> (<code>/overview</code>, &quot;Home&quot; on mobile) shows the status of the active Gmail account and the next useful action. It is Nid&#39;s landing page.</p><hr><h2 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h2><p>&quot;Hello {name}&quot;, followed by the account address and the backup status (&quot;Last backup … ago&quot; or &quot;No backup yet&quot;).</p><hr><h2 id="indicators" tabindex="-1">Indicators <a class="header-anchor" href="#indicators" aria-label="Permalink to &quot;Indicators&quot;">​</a></h2><p>Four clickable cards (2×2 on mobile):</p><table tabindex="0"><thead><tr><th>Card</th><th>Content</th><th>Leads to</th></tr></thead><tbody><tr><td><strong>Mails in Gmail</strong></td><td>number of mails in the account, &quot;N unread&quot;</td><td><a href="./mails.html">Mail</a></td></tr><tr><td><strong>Recoverable</strong></td><td>total size of the scanned senders, &quot;N senders to clean up&quot; (or &quot;Sender scan not run yet&quot;)</td><td><a href="./cleanup.html">Cleanup</a></td></tr><tr><td><strong>NAS backup</strong></td><td>share of Gmail mails already archived (%), number of archived mails, and the space saved by attachment deduplication</td><td><a href="./archives.html">Archives</a></td></tr><tr><td><strong>Active rules</strong></td><td>number of active rules, &quot;N mails processed in the last 30 days&quot;</td><td><a href="./rules.html">Rules &amp; labels</a></td></tr></tbody></table><hr><h2 id="mails-received-—-last-30-days" tabindex="-1">Mails received — last 30 days <a class="header-anchor" href="#mails-received-—-last-30-days" aria-label="Permalink to &quot;Mails received — last 30 days&quot;">​</a></h2><p>One bar per day, from the archives (receipt date of the backed-up mails): the chart is accurate when automatic backup is on. Screen readers get the same figures as a table. <strong>See all</strong> opens <a href="./archives.html">Archives</a>.</p><hr><h2 id="top-senders" tabindex="-1">Top senders <a class="header-anchor" href="#top-senders" aria-label="Permalink to &quot;Top senders&quot;">​</a></h2><p>The senders who send you the most mails, with &quot;N mails · size&quot;. <strong>See all</strong> opens <a href="./cleanup.html">Cleanup</a>.</p><hr><h2 id="suggestions" tabindex="-1">Suggestions <a class="header-anchor" href="#suggestions" aria-label="Permalink to &quot;Suggestions&quot;">​</a></h2><p>Nid spots senders worth handling, for example:</p><ul><li>&quot;{sender}: N mails never read (size).&quot;</li><li>&quot;{sender} takes {size} with N mails.&quot;</li><li>&quot;{sender} sent you N mails you rarely read.&quot;</li></ul><p>Each suggestion offers:</p><ul><li><strong>Unsubscribe and clean up</strong> — same action as in <a href="./cleanup.html#unsubscribe-and-clean-up">Cleanup</a> (disabled if the sender offers no automatic unsubscribe); progress shows on the suggestion, which goes away once the action is done;</li><li><strong>Always do this</strong> — opens the <a href="./rules.html#create-a-rule">rule</a> form prefilled with the sender;</li><li><strong>Ignore</strong> — hides the suggestion.</li></ul><hr><h2 id="heaviest-mails-and-attachments" tabindex="-1">Heaviest mails and attachments <a class="header-anchor" href="#heaviest-mails-and-attachments" aria-label="Permalink to &quot;Heaviest mails and attachments&quot;">​</a></h2><p>The 5 heaviest archived mails (subject, sender, size) and the 5 heaviest attachments (name, mail subject, size). <strong>See all</strong> opens <a href="./archives.html">Archives</a> or <a href="./attachments.html">Attachments</a>, sorted by size.</p><hr><h2 id="running-jobs" tabindex="-1">Running jobs <a class="header-anchor" href="#running-jobs" aria-label="Permalink to &quot;Running jobs&quot;">​</a></h2><p>Tasks currently running, with their progress. <strong>See all</strong> opens <a href="./activity.html">Activity</a>.</p>',27)])])}const p=a(o,[["render",n]]);export{m as __pageData,p as default};
